cat > vectorSql.ts <<'EOF'
/**
 * El SQL vectorial del store: la tabla de cada espacio de embeddings con su
 * índice HNSW sobre la cuantización binaria, y las consultas que la cruzan con
 * el corpus. Es el único sitio del árbol que escribe SQL de pgvector.
 *
 * Todo objeto de la extensión se califica con el esquema donde vive
 * (`<ext>.vector`, `OPERATOR(<ext>.<~>)`, `<ext>.bit_hamming_ops`): la
 * conexión sólo lleva el esquema del store en su `search_path`, y la
 * extensión puede estar habilitada en cualquier otro —en un servicio
 * gestionado no tiene por qué ser `public`—.
 *
 * El nombre de la tabla se deriva del `space_id`, un entero de identidad: la
 * única parte interpolada que no es texto fijo ni una forma ya validada.
 */
import type { EmbeddingShape } from './config.ts'
import { CURRENT_VERSION_CONDITION } from './corpusSql.ts'

export function spaceTableName(spaceId: number): string {
  if (!Number.isInteger(spaceId) || spaceId <= 0) throw new RangeError(`invalid space id ${spaceId}: expected a positive integer`)
  return `space_embeddings_${spaceId}`
}

export function spaceIndexName(spaceId: number): string {
  return `${spaceTableName(spaceId)}_binary_hnsw`
}

/** El tipo de la columna vectorial, calificado con el esquema de la extensión. */
export function vectorType(extensionSchema: string, shape: EmbeddingShape): string {
  return `${extensionSchema}.${shape.representation}(${shape.dimensions})`
}

/** La cuantización binaria de una expresión vectorial, idéntica en el índice y en la consulta. */
function binaryQuantized(extensionSchema: string, expression: string, shape: EmbeddingShape): string {
  return `(${extensionSchema}.binary_quantize(${expression})::bit(${shape.dimensions}))`
}

/** El DDL de la tabla del espacio y de su índice HNSW sobre la cuantización binaria. */
export function createSpaceTableStatements(extensionSchema: string, spaceId: number, shape: EmbeddingShape): string[] {
  const table = spaceTableName(spaceId)
  return [
    `CREATE TABLE ${table} (
       chunk_id UUID PRIMARY KEY REFERENCES document_chunks (chunk_id),
       embedding ${vectorType(extensionSchema, shape)} NOT NULL
     )`,
    `CREATE INDEX ${spaceIndexName(spaceId)} ON ${table}
       USING hnsw (${binaryQuantized(extensionSchema, 'embedding', shape)} ${extensionSchema}.bit_hamming_ops)`,
  ]
}

export function dropSpaceTableStatement(spaceId: number): string {
  return `DROP TABLE ${spaceTableName(spaceId)}`
}

/** Inserta o reemplaza el vector de un chunk: `$1` chunk, `$2` vector como texto. */
export function putEmbeddingQuery(extensionSchema: string, spaceId: number, shape: EmbeddingShape): string {
  return `INSERT INTO ${spaceTableName(spaceId)} (chunk_id, embedding) VALUES ($1, $2::${vectorType(extensionSchema, shape)})
          ON CONFLICT (chunk_id) DO UPDATE SET embedding = EXCLUDED.embedding`
}

/** Los chunks vigentes sin vector en el espacio, en orden estable: `$1` límite. */
export function chunksWithoutEmbeddingQuery(spaceId: number): string {
  return `SELECT c.chunk_id, c.document_id, c.version, c.position, c.text
            FROM document_chunks c
            JOIN documents d ON d.document_id = c.document_id AND ${CURRENT_VERSION_CONDITION}
            LEFT JOIN ${spaceTableName(spaceId)} e ON e.chunk_id = c.chunk_id
           WHERE e.chunk_id IS NULL
           ORDER BY c.document_id, c.version, c.position
           LIMIT $1`
}

/**
 * Los candidatos vigentes más cercanos por distancia de Hamming entre
 * cuantizaciones binarias, ordenados por la misma expresión que indexa el
 * HNSW para que el planificador pueda usarlo: `$1` consulta como texto, `$2`
 * límite. Devuelven el texto del chunk y su identidad de origen: la búsqueda
 * no vuelve a ninguna fuente.
 */
export function binaryCandidatesQuery(extensionSchema: string, spaceId: number, shape: EmbeddingShape): string {
  const query = binaryQuantized(extensionSchema, `$1::${vectorType(extensionSchema, shape)}`, shape)
  const distance = `${binaryQuantized(extensionSchema, 'e.embedding', shape)} OPERATOR(${extensionSchema}.<~>) ${query}`
  return `SELECT e.chunk_id, e.embedding::text AS embedding, c.text, c.document_id, c.version, d.source_identity,
                 ${distance} AS hamming_distance
            FROM ${spaceTableName(spaceId)} e
            JOIN document_chunks c ON c.chunk_id = e.chunk_id
            JOIN documents d ON d.document_id = c.document_id
           WHERE ${CURRENT_VERSION_CONDITION}
           ORDER BY ${distance}
           LIMIT $2`
}
EOF

cd src/packages/semantic-search && cat > corpus.ts <<'EOF'
/**
 * La ingesta del corpus durable: un documento es su identidad de origen
 * (`scope` · `sourceIdentity`) y una secuencia de versiones de chunks. El
 * hash del contenido decide si una reingesta es la misma versión; todo
 * ocurre en una transacción con el documento bloqueado.
 *
 * `sourceIdentity` es texto para trazar (repo@commit:ruta, URL, …) y nunca se
 * abre: el contenido llega entero en `chunks`. No hay edición de chunks: una
 * corrección llega por reingesta, como versión nueva.
 */
import type { SQL } from 'bun'

import { chunkHash, documentHash } from './contentHash.ts'
import { INSERT_CHUNK_QUERY, INSERT_DOCUMENT_QUERY, LOCK_DOCUMENT_QUERY, UPDATE_DOCUMENT_QUERY } from './corpusSql.ts'
import { InvalidCorpusInputError } from './errors.ts'

export type Metadata = Record<string, unknown>

export type DocumentInput = { scope: string; sourceIdentity: string; metadata: Metadata; chunks: readonly string[] }

/** `created`: primera versión · `new-version`: el hash cambió · `unchanged`: no se escribió nada. */
export type IngestStatus = 'created' | 'new-version' | 'unchanged'

export type IngestResult = { status: IngestStatus; documentId: string; version: number }

type LockedDocument = { document_id: string; version: number; content_hash: string }

type Transaction = Pick<SQL, 'unsafe'>

function assertValidDocument(input: DocumentInput): void {
  if (!input.scope.trim()) throw new InvalidCorpusInputError('document scope must be a non-empty string')
  if (!input.sourceIdentity.trim()) throw new InvalidCorpusInputError('document sourceIdentity must be a non-empty string')
  if (input.chunks.length === 0) throw new InvalidCorpusInputError(`document '${input.sourceIdentity}' has no chunks`)
}

function isSameContent(existing: LockedDocument, contentHash: string): boolean {
  return existing.content_hash === contentHash
}

async function insertChunks(tx: Transaction, documentId: string, version: number, chunks: readonly string[]): Promise<void> {
  for (const [position, text] of chunks.entries()) {
    await tx.unsafe(INSERT_CHUNK_QUERY, [documentId, version, position, text, chunkHash(text)])
  }
}

async function createDocument(tx: Transaction, input: DocumentInput, contentHash: string): Promise<IngestResult> {
  const [row] = (await tx.unsafe(INSERT_DOCUMENT_QUERY, [input.scope, input.sourceIdentity, contentHash, JSON.stringify(input.metadata)])) as {
    document_id: string
  }[]
  if (!row) throw new Error(`inserting document '${input.sourceIdentity}' returned no row`)
  await insertChunks(tx, row.document_id, 1, input.chunks)
  return { status: 'created', documentId: row.document_id, version: 1 }
}

async function addVersion(tx: Transaction, existing: LockedDocument, input: DocumentInput, contentHash: string): Promise<IngestResult> {
  const version = existing.version + 1
  await tx.unsafe(UPDATE_DOCUMENT_QUERY, [existing.document_id, version, contentHash, JSON.stringify(input.metadata)])
  await insertChunks(tx, existing.document_id, version, input.chunks)
  return { status: 'new-version', documentId: existing.document_id, version }
}

/**
 * Ingiere un documento. Mismo origen y mismo hash: `unchanged`, sin escribir
 * nada —tampoco la metadata—. Hash distinto: versión nueva con sus chunks, y
 * la anterior deja de ser buscable (su texto se conserva para los análisis).
 */
export async function ingestDocument(sql: SQL, input: DocumentInput): Promise<IngestResult> {
  assertValidDocument(input)
  const contentHash = documentHash(input.chunks)
  return sql.begin(async tx => {
    const [existing] = (await tx.unsafe(LOCK_DOCUMENT_QUERY, [input.scope, input.sourceIdentity])) as LockedDocument[]
    if (!existing) return createDocument(tx, input, contentHash)
    if (isSameContent(existing, contentHash)) return { status: 'unchanged', documentId: existing.document_id, version: existing.version }
    return addVersion(tx, existing, input, contentHash)
  })
}
